import { Component } from 'react';

// 全域錯誤保護：避免任何一個頁面的程式錯誤讓整個系統變成空白畫面
// 抓到錯誤時顯示錯誤訊息 + 重新整理按鈕，而不是讓使用者以為系統打不開
export default class ErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { error: null };
  }

  static getDerivedStateFromError(error) {
    return { error };
  }

  componentDidCatch(error, info) {
    console.error('App crashed:', error, info?.componentStack);
  }

  render() {
    if (this.state.error) {
      return (
        <div style={{
          minHeight: '100vh', display: 'flex', flexDirection: 'column',
          alignItems: 'center', justifyContent: 'center', gap: 16, padding: 24,
          textAlign: 'center', background: 'var(--bg, #0a0a14)', color: 'var(--text, #e0e0ff)',
        }}>
          <div style={{ fontSize: 40 }}>⚠</div>
          <div style={{ fontSize: 18, fontWeight: 700 }}>系統發生錯誤，畫面無法顯示</div>
          <div style={{ fontSize: 14, color: 'var(--muted, #8888aa)', maxWidth: 480 }}>
            請點擊下方按鈕重新整理。如果重新整理後仍然發生，請截圖這個畫面回報給管理員。
          </div>
          <div style={{
            fontSize: 12, fontFamily: 'monospace', color: 'var(--pink, #ff006e)',
            background: 'rgba(255,0,110,0.08)', border: '1px solid rgba(255,0,110,0.3)',
            borderRadius: 4, padding: '8px 12px', maxWidth: 560, overflow: 'auto', textAlign: 'left',
          }}>
            {String(this.state.error?.message || this.state.error)}
          </div>
          <button
            onClick={() => window.location.reload()}
            style={{
              background: '#00f5ff', color: '#000', border: 'none', borderRadius: 4,
              padding: '10px 24px', fontWeight: 700, cursor: 'pointer', fontSize: 14,
            }}>
            ◈ 重新整理
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}
